//! Cross-binding golden vectors for sealed grants
//! (`conformance/vectors/grants.json`) and ticket relay folding
//! (`conformance/vectors/ticket.json`), checked against the core
//! implementation every binding wraps.
//!
//! The files are generated by `aster/tests/it/grant_vectors.rs` (which also
//! checks the `aster` facade); see there to regenerate.

use std::net::SocketAddr;
use std::path::PathBuf;

use aster_transport_core::grants::{
    check_grant_role, grant_key, grant_recipient_public_key, open_grant, open_grant_with_key,
    open_namespace_grant, reconcile_grant, reconcile_namespace_grant, seal_grant,
    seal_grant_to_key, seal_namespace_grant, GrantContext, GrantOutcome,
};
use aster_transport_core::hpke_envelope::{
    hpke_public_key_from_private, hpke_x25519_secret_from_identity,
};
use aster_transport_core::namespace::CoreNamespaceCapability;
use aster_transport_core::ticket::{relay_url_to_socket, socket_to_relay_url};
use serde_json::Value;

fn load(name: &str) -> Value {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../conformance/vectors")
        .join(name);
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}

fn s<'a>(v: &'a Value, k: &str) -> &'a str {
    v[k].as_str()
        .unwrap_or_else(|| panic!("missing string {k}"))
}

fn h(v: &Value, k: &str) -> Vec<u8> {
    hex::decode(s(v, k)).unwrap()
}

fn key32(v: &Value, k: &str) -> [u8; 32] {
    h(v, k).try_into().unwrap()
}

/// Owned context fields parsed from a vector.
struct Ctx {
    app: String,
    granter: String,
    recipient: String,
    resource: Vec<u8>,
    path: String,
    role: String,
}

impl Ctx {
    fn from_json(v: &Value) -> Self {
        Ctx {
            app: s(v, "app").into(),
            granter: s(v, "granter").into(),
            recipient: s(v, "recipient").into(),
            resource: h(v, "resource_hex"),
            path: s(v, "path").into(),
            role: s(v, "role").into(),
        }
    }

    fn borrow(&self) -> GrantContext<'_> {
        GrantContext {
            app: &self.app,
            granter: &self.granter,
            recipient: &self.recipient,
            resource: &self.resource,
            path: &self.path,
            role: &self.role,
        }
    }
}

fn open_by_scheme(v: &Value, c: &Ctx) -> anyhow::Result<Vec<u8>> {
    let env = h(v, "envelope_hex");
    let key = key32(v, "recipient_key_hex");
    let payload = match s(v, "scheme") {
        "identity" => open_grant(&key, &c.borrow(), &env)?,
        "x25519" => open_grant_with_key(&key, &c.borrow(), &env)?,
        other => panic!("unknown scheme {other}"),
    };
    Ok(payload.into_secret())
}

#[test]
fn aad_vectors() {
    let doc = load("grants.json");
    for v in doc["aad"].as_array().unwrap() {
        let c = Ctx::from_json(&v["context"]);
        assert_eq!(
            hex::encode(c.borrow().aad()),
            s(v, "aad_hex"),
            "{}",
            s(v, "name")
        );
    }
}

#[test]
fn grant_key_vectors() {
    let doc = load("grants.json");
    for v in doc["grant_key"].as_array().unwrap() {
        assert_eq!(grant_key(s(v, "prefix"), s(v, "recipient")), s(v, "key"));
    }
}

#[test]
fn open_vectors() {
    let doc = load("grants.json");
    for v in doc["open"].as_array().unwrap() {
        let name = s(v, "name");
        let c = Ctx::from_json(&v["context"]);
        let plaintext = open_by_scheme(v, &c).unwrap_or_else(|e| panic!("{name}: {e}"));
        assert_eq!(hex::encode(&plaintext), s(v, "plaintext_hex"), "{name}");

        // Re-sealing (randomized) under the same context must open too.
        let resealed = match s(v, "scheme") {
            "identity" => {
                let env = seal_grant(&c.borrow(), &plaintext).unwrap();
                open_grant(&key32(v, "recipient_key_hex"), &c.borrow(), &env).unwrap()
            }
            _ => {
                let public = hpke_public_key_from_private(&h(v, "recipient_key_hex")).unwrap();
                assert_eq!(hex::encode(public), s(v, "recipient_public_hex"));
                let env = seal_grant_to_key(&public, &c.borrow(), &plaintext).unwrap();
                open_grant_with_key(&key32(v, "recipient_key_hex"), &c.borrow(), &env).unwrap()
            }
        };
        assert_eq!(resealed.expose_secret(), &plaintext[..]);
    }
    for v in doc["open_invalid"].as_array().unwrap() {
        let c = Ctx::from_json(&v["context"]);
        assert!(open_by_scheme(v, &c).is_err(), "{} opened", s(v, "name"));
    }
}

#[test]
fn identity_scheme_matches_explicit_key_scheme() {
    // seal_grant == seal_grant_to_key(grant_recipient_public_key(recipient)),
    // and open_grant == open_grant_with_key(x25519 secret from identity).
    let doc = load("grants.json");
    let v = &doc["open"][0];
    assert_eq!(s(v, "scheme"), "identity");
    let c = Ctx::from_json(&v["context"]);
    let x_secret = hpke_x25519_secret_from_identity(&key32(v, "recipient_key_hex"));
    let opened = open_grant_with_key(&x_secret, &c.borrow(), &h(v, "envelope_hex")).unwrap();
    assert_eq!(hex::encode(opened.expose_secret()), s(v, "plaintext_hex"));
    let public = grant_recipient_public_key(&c.recipient).unwrap();
    assert_eq!(public, hpke_public_key_from_private(&x_secret).unwrap());
}

#[test]
fn namespace_vectors() {
    let doc = load("grants.json");
    for v in doc["namespace_open"].as_array().unwrap() {
        let c = Ctx::from_json(&v["context"]);
        let secret = key32(v, "recipient_secret_hex");
        let cap = open_namespace_grant(&secret, &c.borrow(), &h(v, "envelope_hex")).unwrap();
        assert_eq!(hex::encode(cap.encode_fory()), s(v, "capability_hex"));
        assert_eq!(cap.can_write(), v["can_write"].as_bool().unwrap());
        // And it reseals under the same rule.
        let env = seal_namespace_grant(&c.borrow(), &cap).unwrap();
        assert_eq!(
            open_namespace_grant(&secret, &c.borrow(), &env).unwrap(),
            cap
        );
    }
    for v in doc["namespace_open_invalid"].as_array().unwrap() {
        let c = Ctx::from_json(&v["context"]);
        let secret = key32(v, "recipient_secret_hex");
        let env = h(v, "envelope_hex");
        assert!(open_grant(&secret, &c.borrow(), &env).is_ok());
        let err = open_namespace_grant(&secret, &c.borrow(), &env).unwrap_err();
        assert!(err.to_string().contains("does not match the capability"));
    }
    for v in doc["role_rule"].as_array().unwrap() {
        let ok = check_grant_role(s(v, "role"), v["can_write"].as_bool().unwrap()).is_ok();
        assert_eq!(ok, v["ok"].as_bool().unwrap(), "role {}", s(v, "role"));
    }
}

fn summarize<T>(
    outcome: GrantOutcome<T>,
    bytes: impl FnOnce(T) -> Vec<u8>,
) -> (&'static str, Value) {
    let drops = outcome.drops_capability();
    let out = match outcome {
        GrantOutcome::Active(v) => ("active", Value::String(hex::encode(bytes(v)))),
        GrantOutcome::Revoked { reason, role } => (
            "revoked",
            serde_json::json!({ "reason": reason, "role": role }),
        ),
        GrantOutcome::Unopenable(e) => ("unopenable", Value::String(e.to_string())),
        GrantOutcome::Absent => ("absent", Value::Null),
    };
    assert_eq!(drops, matches!(out.0, "revoked" | "unopenable"));
    out
}

#[test]
fn reconcile_vectors() {
    let doc = load("grants.json");
    for v in doc["reconcile"].as_array().unwrap() {
        let name = s(v, "name");
        let c = Ctx::from_json(&v["context"]);
        let secret = key32(v, "recipient_secret_hex");
        let record = v["record_hex"].as_str().map(|x| hex::decode(x).unwrap());
        let expect = &v["outcome"];
        let (kind, detail) = match s(v, "payload") {
            "raw" => summarize(
                reconcile_grant(&secret, &c.borrow(), record.as_deref()),
                |p| p.into_secret(),
            ),
            "namespace" => summarize(
                reconcile_namespace_grant(&secret, &c.borrow(), record.as_deref()),
                |cap: CoreNamespaceCapability| cap.encode_fory(),
            ),
            other => panic!("unknown payload {other}"),
        };
        assert_eq!(kind, s(expect, "kind"), "{name}");
        match kind {
            "active" => {
                let want = expect["plaintext_hex"]
                    .as_str()
                    .or(expect["capability_hex"].as_str())
                    .unwrap();
                assert_eq!(detail.as_str().unwrap(), want, "{name}");
            }
            "revoked" => {
                assert_eq!(detail["reason"], expect["reason"], "{name}");
                assert_eq!(detail["role"], expect["role"], "{name}");
            }
            "unopenable" => {
                if let Some(needle) = expect["error_contains"].as_str() {
                    assert!(detail.as_str().unwrap().contains(needle), "{name}");
                }
            }
            _ => {}
        }
    }
}

#[test]
fn ticket_relay_vectors() {
    let doc = load("ticket.json");
    for v in doc["relay_url_to_socket"].as_array().unwrap() {
        let url = s(v, "url");
        let got = relay_url_to_socket(url);
        if v["error"].as_bool() == Some(true) {
            assert!(got.is_err(), "{url}: {got:?}");
        } else {
            let got = got.unwrap().map(|a| a.to_string());
            assert_eq!(got.as_deref(), v["socket"].as_str(), "{url}");
        }
    }
    for v in doc["socket_to_relay_url"].as_array().unwrap() {
        let addr: SocketAddr = s(v, "socket").parse().unwrap();
        let url = socket_to_relay_url(&addr);
        assert_eq!(url, s(v, "url"));
        // The URL folds back to the same socket.
        assert_eq!(relay_url_to_socket(&url).unwrap(), Some(addr));
    }
}
